class CustomStack {
    private final int[] values;
    private int size=0;
    public CustomStack(int maxSize){
        values=new int[maxSize];
    }
    public void push(int x){
        if(size<values.length)values[size++]=x;
    }
    public int pop(){
        return size==0?-1:values[--size];
    }
    public void increment(int k,int val){
        for(int i=0;i<Math.min(k,size);i++)values[i]+=val;
    }
}

code.kotlin:
class CustomStack(maxSize:Int){
    private val values=IntArray(maxSize);
    private var size=0;
    fun push(x:Int){
        if(size<values.size)values[size++]=x
    };
    fun pop():Int{
        if(size==0)return -1;
        size--;
        return values[size]
    };
    fun increment(k:Int,`val`:Int){
        for(i in 0 until minOf(k,size))values[i]+=`val`
    }
}

